// Pipeline Dependency Hazard Example
int a, b;
a = value + 1; // Stage 1 (Write-back)
b = a * 2;     // Stage 2 (Read A too soon, potential stall)

// Avoiding Stalls via Interleaving/Loop Unrolling
int i1, i2;
for (int i=0; i<N; i+=2) {
  i1 = arr[i];    // Load 1
  i2 = arr[i+1];  // Load 2 (Independent instruction fills pipe)
  i1 = i1 + 10;
  i2 = i2 + 10;   // Independent operations
}


// SIMD Vectorization (SSE/AVX Intrinsics)
// Operate on 4 single-precision floats simultaneously (__m128 = 128 bits)
__m128 va, vb, vc;
float* A_ptr, *B_ptr, *C_ptr;

// Load data into vector registers
va = _mm_loadu_ps(A_ptr);
vb = _mm_loadu_ps(B_ptr);

// Vector Addition (e.g., VADDPS on AVX)
// 4 parallel additions executed in one cycle
vc = _mm_add_ps(va, vb);

// Store results
_mm_storeu_ps(C_ptr, vc);
